def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    supply = day_context['supply']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive_opponents = []
    prev_bids = []
    aggressive_bids = []
    desperate_count = 0

    for opp in opponents_status.values():
        if opp.get('alive'):
            alive_opponents.append(opp)
            if opp.get('hp', 0) <= 3 or opp.get('no_water_days', 0) >= 1:
                desperate_count += 1
            prev = opp.get('previous_trace', {})
            if prev and prev.get('bid') is not None:
                bid = prev.get('bid', 0)
                prev_bids.append(bid)
                if bid >= DAILY_SALARY * 0.8:
                    aggressive_bids.append(bid)

    if budget <= 0:
        return 0.0

    if not alive_opponents:
        return float(min(budget, DAILY_SALARY * 0.25))

    if prev_bids:
        highest_prev = max(prev_bids)
        avg_prev = sum(prev_bids) / len(prev_bids)
    else:
        highest_prev = 0.0
        avg_prev = 0.0

    supply_pressure = (MAX_SUPPLY - supply) / float(MAX_SUPPLY - MIN_SUPPLY)
    if supply_pressure < 0:
        supply_pressure = 0.0
    if supply_pressure > 1:
        supply_pressure = 1.0

    risk = 0.0
    if hp <= 2:
        risk += 0.5
    elif hp <= 4:
        risk += 0.3

    if no_water_days >= 2:
        risk += 0.35
    elif no_water_days >= 1:
        risk += 0.2

    risk += 0.2 * supply_pressure
    risk += min(0.2, 0.05 * desperate_count)
    if highest_prev >= DAILY_SALARY * 0.8:
        risk += 0.15
    elif highest_prev >= DAILY_SALARY * 0.5:
        risk += 0.08

    if risk >= 0.8:
        target = max(DAILY_SALARY * 0.95, highest_prev + 2.0)
    elif risk >= 0.55:
        target = max(DAILY_SALARY * 0.72, avg_prev + 3.0, highest_prev * 0.9)
    elif risk >= 0.3:
        target = max(DAILY_SALARY * 0.48, avg_prev + 1.5)
    else:
        target = DAILY_SALARY * (0.28 + 0.12 * supply_pressure)
        if highest_prev > 0:
            target = max(target, min(highest_prev * 0.65, DAILY_SALARY * 0.45))

    if budget < DAILY_SALARY * 0.5 and (hp > 4 and no_water_days == 0):
        target = min(target, budget * 0.55)

    target = min(target, budget)
    if target < 0:
        target = 0.0

    return float(target)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 7
    DAILY_SALARY = 80
    supply = day_context['supply']
    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    if not alive_opponents:
        return min(my_status['budget'], 20.0)

    yesterday_bids = [o['previous_trace']['bid'] for o in alive_opponents if o.get('previous_trace') and o['previous_trace'].get('bid') is not None]

    avg_prev_bid = sum(yesterday_bids) / len(yesterday_bids) if yesterday_bids else 40.0

    if my_status['hp'] <= 3:
        return min(my_status['budget'], DAILY_SALARY * 0.9)

    if supply < WATER_REQ * 1.5:
        return min(my_status['budget'], avg_prev_bid * 1.1)

    return min(my_status['budget'], max(25.0, avg_prev_bid * 0.8))
